-- =====================================================================
-- Locale_403.lua — v4.0.3 Quest Journal and Mythic+ Run Analysis V2
-- =====================================================================

TomoMod_RegisterLocale("enUS", {
    ["wn_403_quest_journal_skin_removed"] = "Removed — The experimental Quest Journal and World Map skin has been removed because it caused errors in game. Blizzard's original journal visuals and behaviour remain untouched; the independent World Quests tab is still available.",
    ["wn_403_world_quest_tab"] = "Changed — The former World Quest panel beside the world map has been replaced by a native World Quests tab inside the Quest Journal, keeping quests and map navigation in one window.",
    ["wn_403_world_quest_cards"] = "New — World Quests are displayed as compact cards with reward icons, rarity accents, elite markers, zone and remaining time. Search, sorting by time, reward, zone or name, a draggable scrollbar and one-click map navigation are built in.",
    ["wn_403_world_quest_sort"] = "Fixed — World Quest sorting now tolerates missing or non-numeric times, reward data and quest IDs. Empty entries are ordered consistently, equal values use a deterministic quest-ID tie-break and both ascending and descending paths are explicit.",
    ["wn_403_bags_separate_skin"] = "New — Separate bag mode keeps Blizzard's individual container windows and gives them a complete TomoMod skin: dark panels and headers, azure borders, Poppins titles, recessed slots, cropped icons and accent feedback on hover. Returning to combined mode or disabling Bags restores the original native artwork.",
    ["wn_403_bags_tracked_currencies"] = "New — The Bags V4 sidebar now lists every currency marked Show in Backpack in compact two-column tiles with its icon, formatted quantity and native tooltip. The localized section appears only when currencies are tracked and refreshes whenever currency data changes.",
    ["wn_403_bags_currency_reliability"] = "Fixed — Hiding Blizzard's backpack in combined mode could reduce its calculated watched-currency capacity to one. TomoMod now preserves the traditional three slots only in that mode and reads the persisted isShowInBackpack state directly, so additional tracked currencies no longer disappear.",
    ["wn_403_color_picker_skin"] = "New — Blizzard's global colour picker now has a complete TomoMod skin with layered dark body, header and footer surfaces, azure borders, Poppins typography and themed controls. The hex field, colour swatches, value and alpha areas and opacity slider all share the same visual language.",
    ["wn_403_color_picker_compatibility"] = "Changed — The skin supports both the current Retail and legacy ColorPickerFrame layouts, initializes when Blizzard's load-on-demand picker becomes available and reapplies whenever it opens. Blizzard still owns colour selection, confirmation and cancellation callbacks.",
    ["wn_403_color_picker_buttons"] = "Fixed — Retail panel buttons no longer repaint their persistent Left, Middle and Right background textures over the TomoMod skin. The custom close control also preserves Blizzard's original cancellation callback and previous colour values.",
    ["wn_403_waypoint_inner_ring"] = "Changed — The waypoint beacon now keeps only its compact inner ring. The oversized translucent outer glow and its colour and size updates have been removed for a cleaner marker, while the beam, centre dot and navigation arrow retain their existing behaviour.",
    ["wn_403_survival_tab"] = "New — Mythic+ Run Analysis gains a Survival tab next to the Summary. Both views share the same window, so the run summary, group performance and splits stay one click away from the death analysis.",
    ["wn_403_survival_chronology"] = "New — The Survival tab lists every death recorded during the key in chronological order, with its run time and the player's class colour. Selecting a row opens that death in the detail panel.",
    ["wn_403_survival_detail"] = "New — Your own deaths are shown in full: the fatal event with its icon, name, damage and overkill, your maximum health, and the last ten events before you died, each with the time separating it from the killing blow and the health you had left.",
    ["wn_403_survival_collector"] = "New — The death collector now loads with TomoMod itself instead of the load-on-demand Mythic+ Studio. Tracking begins when the key begins, so a run is never lost because the Studio had not been opened yet.",
    ["wn_403_survival_unit_events"] = "Changed — Deaths are read from unit-state transitions rather than the combat log, which is protected on the current client. Group health and flag events give the same chronology without touching it.",
    ["wn_403_survival_recap_bridge"] = "Changed — Your pre-death timeline is copied from Blizzard's death recap through the guarded TomoDamageMeter bridge. The recap is not readable the instant you die, so it is retried for about two and a half seconds before the death is marked as having no readable detail.",
    ["wn_403_survival_reliability"] = "Changed — The number of deaths observed is cross-checked against the game's own count for the key. A matching run is reported as complete tracking, while a key joined late or reloaded mid-run is reported as partial tracking with both figures, instead of presenting an incomplete list as the whole story.",
    ["wn_403_survival_history"] = "New — The death chronology is stored in the run snapshot alongside the existing performance data, so reopening a past key from Run History shows the deaths that run actually had instead of nothing at all.",
    ["wn_403_survival_localization"] = "Changed — Every label of the Survival tab — the tabs themselves, the chronology, the tracking state, the fatal event, the timeline and the messages shown when no detail is available — is translated in all six supported languages.",
})

TomoMod_RegisterLocale("frFR", {
    ["wn_403_quest_journal_skin_removed"] = "Suppression — L'habillage expérimental du Journal de quêtes et de la carte du monde a été retiré parce qu'il provoquait des erreurs en jeu. L'apparence et le comportement Blizzard restent intacts ; l'onglet indépendant des quêtes mondiales reste disponible.",
    ["wn_403_world_quest_tab"] = "Modification — L'ancien panneau des quêtes mondiales placé à côté de la carte est remplacé par un onglet natif dans le Journal de quêtes, réunissant les quêtes et la navigation sur la carte dans une même fenêtre.",
    ["wn_403_world_quest_cards"] = "Nouveauté — Les quêtes mondiales s'affichent sous forme de cartes compactes avec icône de récompense, couleur de rareté, marqueur élite, zone et temps restant. La recherche, le tri par temps, récompense, zone ou nom, la barre de défilement et l'accès direct à la carte sont intégrés.",
    ["wn_403_world_quest_sort"] = "Correction — Le tri des quêtes mondiales accepte désormais les temps, récompenses et identifiants de quête manquants ou non numériques. Les entrées vides sont classées de façon cohérente, les valeurs identiques sont départagées par l'identifiant et les deux sens de tri sont explicites.",
    ["wn_403_bags_separate_skin"] = "Nouveauté — Le mode sacs séparés conserve les fenêtres individuelles de Blizzard et leur applique un habillage TomoMod complet : panneaux et en-têtes sombres, bordures azur, titres Poppins, cases en retrait, icônes recadrées et accent au survol. Revenir au mode combiné ou désactiver les sacs restaure l'apparence native d'origine.",
    ["wn_403_bags_tracked_currencies"] = "Nouveauté — La barre latérale de Bags V4 liste maintenant chaque monnaie marquée Afficher dans le sac à dos sous forme de vignettes compactes sur deux colonnes, avec son icône, sa quantité formatée et son infobulle native. Cette section localisée apparaît uniquement lorsque des monnaies sont suivies et s'actualise avec leurs données.",
    ["wn_403_bags_currency_reliability"] = "Correction — Masquer le sac à dos Blizzard en mode combiné pouvait réduire à une seule la capacité calculée des monnaies suivies. TomoMod préserve désormais les trois emplacements habituels uniquement dans ce mode et lit directement l'état persistant isShowInBackpack, afin que les monnaies supplémentaires ne disparaissent plus.",
    ["wn_403_color_picker_skin"] = "Nouveauté — Le sélecteur de couleurs global de Blizzard dispose maintenant d'un habillage TomoMod complet avec corps, en-tête et pied de page sombres superposés, bordures azur, police Poppins et commandes assorties. Le champ hexadécimal, les aperçus, les zones de valeur et d'alpha ainsi que le curseur d'opacité partagent la même identité visuelle.",
    ["wn_403_color_picker_compatibility"] = "Modification — L'habillage prend en charge les versions Retail actuelle et héritée de ColorPickerFrame, s'initialise lorsque le sélecteur Blizzard à chargement différé devient disponible et se réapplique à chaque ouverture. Blizzard conserve la sélection de couleur et les callbacks de validation et d'annulation.",
    ["wn_403_color_picker_buttons"] = "Correction — Les boutons de panneau Retail ne redessinent plus leurs textures persistantes Left, Middle et Right par-dessus l'habillage TomoMod. Le bouton de fermeture personnalisé conserve également le callback d'annulation Blizzard et les valeurs de couleur précédentes.",
    ["wn_403_waypoint_inner_ring"] = "Modification — La balise de point de passage conserve uniquement son anneau intérieur compact. Le grand halo extérieur translucide et ses mises à jour de couleur et de taille ont été supprimés pour obtenir un repère plus net, tandis que le faisceau, le point central et la flèche de navigation gardent leur comportement actuel.",
    ["wn_403_survival_tab"] = "Nouveauté — L'Analyse de run Mythic+ gagne un onglet Survie à côté du Résumé. Les deux vues partagent la même fenêtre : le résumé du run, les performances du groupe et les splits restent à un clic de l'analyse des morts.",
    ["wn_403_survival_chronology"] = "Nouveauté — L'onglet Survie liste chaque mort enregistrée pendant la clé, dans l'ordre chronologique, avec son temps de run et la couleur de classe du joueur. Sélectionner une ligne ouvre cette mort dans le panneau de détail.",
    ["wn_403_survival_detail"] = "Nouveauté — Tes propres morts sont détaillées : l'événement fatal avec son icône, son nom, ses dégâts et son overkill, ta vie maximale, et les dix derniers événements avant ta mort, chacun avec le temps qui le sépare du coup fatal et la vie qu'il te restait.",
    ["wn_403_survival_collector"] = "Nouveauté — Le collecteur de morts est désormais chargé avec TomoMod lui-même et non avec le Studio Mythic+ à la demande. Le suivi démarre en même temps que la clé : un run n'est plus perdu parce que le Studio n'avait pas encore été ouvert.",
    ["wn_403_survival_unit_events"] = "Modification — Les morts sont lues à partir des transitions d'état des unités plutôt que du journal de combat, protégé sur le client actuel. Les événements de vie et d'indicateurs du groupe donnent la même chronologie sans y toucher.",
    ["wn_403_survival_recap_bridge"] = "Modification — Ta chronologie d'avant-mort est copiée depuis le récapitulatif de mort de Blizzard via le pont protégé de TomoDamageMeter. Ce récapitulatif n'est pas lisible à l'instant de la mort : il est donc réessayé pendant environ deux secondes et demie avant que la mort soit marquée comme sans détail lisible.",
    ["wn_403_survival_reliability"] = "Modification — Le nombre de morts observées est recoupé avec le compteur du jeu pour la clé. Un run cohérent est annoncé en suivi complet ; une clé rejointe en cours ou rechargée en plein run est annoncée en suivi partiel avec les deux chiffres, plutôt que de présenter une liste incomplète comme si elle était complète.",
    ["wn_403_survival_history"] = "Nouveauté — La chronologie des morts est stockée dans l'instantané du run, à côté des données de performance existantes : rouvrir une ancienne clé depuis l'Historique des runs affiche les morts que ce run a réellement eues au lieu de rien du tout.",
    ["wn_403_survival_localization"] = "Modification — Tous les libellés de l'onglet Survie — les onglets eux-mêmes, la chronologie, l'état du suivi, l'événement fatal, la timeline et les messages affichés en l'absence de détail — sont traduits dans les six langues prises en charge.",
})

TomoMod_RegisterLocale("deDE", {
    ["wn_403_quest_journal_skin_removed"] = "Entfernt — Der experimentelle Skin für Questtagebuch und Weltkarte wurde entfernt, weil er im Spiel Fehler verursachte. Blizzards ursprüngliche Darstellung und Funktion bleiben unangetastet; der unabhängige Weltquests-Reiter ist weiterhin verfügbar.",
    ["wn_403_world_quest_tab"] = "Geändert — Das bisherige Weltquest-Fenster neben der Weltkarte wurde durch einen nativen Weltquests-Reiter im Questtagebuch ersetzt. Quests und Kartennavigation befinden sich damit in einem gemeinsamen Fenster.",
    ["wn_403_world_quest_cards"] = "Neu — Weltquests erscheinen als kompakte Karten mit Belohnungssymbol, Seltenheitsfarbe, Elite-Markierung, Zone und verbleibender Zeit. Suche, Sortierung nach Zeit, Belohnung, Zone oder Name, eine ziehbare Bildlaufleiste und Kartennavigation per Klick sind integriert.",
    ["wn_403_world_quest_sort"] = "Behoben — Die Sortierung der Weltquests verträgt jetzt fehlende oder nicht numerische Zeiten, Belohnungsdaten und Quest-IDs. Leere Einträge werden einheitlich eingeordnet, gleiche Werte eindeutig über die Quest-ID entschieden und beide Sortierrichtungen ausdrücklich behandelt.",
    ["wn_403_bags_separate_skin"] = "Neu — Der Modus für getrennte Taschen behält Blizzards einzelne Behälterfenster und versieht sie mit einem vollständigen TomoMod-Skin: dunkle Flächen und Kopfzeilen, azurblaue Ränder, Poppins-Titel, vertiefte Plätze, beschnittene Symbole und Akzent beim Überfahren. Beim Wechsel zurück zum kombinierten Modus oder Deaktivieren der Taschen wird die ursprüngliche Gestaltung wiederhergestellt.",
    ["wn_403_bags_tracked_currencies"] = "Neu — Die Seitenleiste von Bags V4 zeigt jetzt jede mit Im Rucksack anzeigen markierte Währung als kompakte Kachel in zwei Spalten mit Symbol, formatierter Menge und nativem Tooltip. Der lokalisierte Bereich erscheint nur bei verfolgten Währungen und wird bei Änderungen der Währungsdaten aktualisiert.",
    ["wn_403_bags_currency_reliability"] = "Behoben — Das Ausblenden von Blizzards Rucksack im kombinierten Modus konnte die berechnete Kapazität verfolgter Währungen auf eine reduzieren. TomoMod bewahrt nur in diesem Modus die üblichen drei Plätze und liest den gespeicherten Status isShowInBackpack direkt, sodass weitere verfolgte Währungen nicht mehr verschwinden.",
    ["wn_403_color_picker_skin"] = "Neu — Blizzards globaler Farbwähler besitzt jetzt einen vollständigen TomoMod-Skin mit gestaffelten dunklen Flächen für Inhalt, Kopf- und Fußzeile, azurblauen Rändern, Poppins-Schrift und passenden Bedienelementen. Hexadezimalfeld, Farbvorschauen, Wert- und Alphabereich sowie Deckkraftregler folgen derselben Gestaltung.",
    ["wn_403_color_picker_compatibility"] = "Geändert — Der Skin unterstützt sowohl das aktuelle Retail- als auch das ältere ColorPickerFrame-Layout, initialisiert sich beim Laden von Blizzards verzögertem Farbwähler und wird bei jedem Öffnen erneut angewendet. Farbauswahl sowie Bestätigungs- und Abbruchrückrufe bleiben vollständig bei Blizzard.",
    ["wn_403_color_picker_buttons"] = "Behoben — Retail-Schaltflächen zeichnen ihre dauerhaften Hintergrundtexturen Left, Middle und Right nicht mehr über den TomoMod-Skin. Auch die eigene Schließen-Schaltfläche bewahrt Blizzards ursprünglichen Abbruchrückruf und die vorherigen Farbwerte.",
    ["wn_403_waypoint_inner_ring"] = "Geändert — Die Wegpunktmarkierung behält nur noch ihren kompakten inneren Ring. Der große durchscheinende Außenleuchtring samt Farb- und Größenanpassung wurde für eine klarere Markierung entfernt; Strahl, Mittelpunkt und Navigationspfeil funktionieren unverändert weiter.",
    ["wn_403_survival_tab"] = "Neu — Die Mythic+-Runanalyse erhält neben der Übersicht einen Reiter Überleben. Beide Ansichten teilen sich dasselbe Fenster, sodass Runzusammenfassung, Gruppenleistung und Splits nur einen Klick von der Todesanalyse entfernt bleiben.",
    ["wn_403_survival_chronology"] = "Neu — Der Reiter Überleben listet jeden während des Schlüssels erfassten Tod in chronologischer Reihenfolge auf, mit Runzeit und Klassenfarbe des Spielers. Ein Klick auf eine Zeile öffnet diesen Tod im Detailbereich.",
    ["wn_403_survival_detail"] = "Neu — Deine eigenen Tode werden vollständig dargestellt: das tödliche Ereignis mit Symbol, Name, Schaden und Overkill, deine maximale Gesundheit sowie die letzten zehn Ereignisse vor deinem Tod, jeweils mit dem Abstand zum tödlichen Treffer und der verbliebenen Gesundheit.",
    ["wn_403_survival_collector"] = "Neu — Der Todessammler wird jetzt mit TomoMod selbst geladen statt mit dem nachladbaren Mythic+-Studio. Die Erfassung startet mit dem Schlüssel, sodass kein Run mehr verloren geht, nur weil das Studio noch nicht geöffnet war.",
    ["wn_403_survival_unit_events"] = "Geändert — Tode werden aus Zustandswechseln der Einheiten gelesen statt aus dem Kampflog, das auf dem aktuellen Client geschützt ist. Gesundheits- und Flag-Ereignisse der Gruppe liefern dieselbe Chronologie, ohne es anzufassen.",
    ["wn_403_survival_recap_bridge"] = "Geändert — Deine Ereigniskette vor dem Tod wird über die abgesicherte TomoDamageMeter-Brücke aus Blizzards Todesrückblick kopiert. Der Rückblick ist im Moment des Todes noch nicht lesbar und wird daher rund zweieinhalb Sekunden lang erneut abgefragt, bevor der Tod als ohne lesbare Details markiert wird.",
    ["wn_403_survival_reliability"] = "Geändert — Die Zahl der beobachteten Tode wird mit dem spieleigenen Zähler des Schlüssels abgeglichen. Ein übereinstimmender Run wird als vollständige Erfassung gemeldet, ein spät betretener oder mitten im Run neu geladener Schlüssel dagegen als teilweise Erfassung mit beiden Werten — statt eine unvollständige Liste als das Ganze auszugeben.",
    ["wn_403_survival_history"] = "Neu — Die Todeschronologie wird zusammen mit den bestehenden Leistungsdaten im Run-Schnappschuss gespeichert. Das erneute Öffnen eines früheren Schlüssels aus dem Runverlauf zeigt damit die Tode, die dieser Run tatsächlich hatte, statt gar nichts.",
    ["wn_403_survival_localization"] = "Geändert — Sämtliche Beschriftungen des Reiters Überleben — die Reiter selbst, die Chronologie, der Erfassungsstatus, das tödliche Ereignis, die Zeitleiste und die Hinweise bei fehlenden Details — sind in allen sechs unterstützten Sprachen übersetzt.",
})

TomoMod_RegisterLocale("esES", {
    ["wn_403_quest_journal_skin_removed"] = "Eliminado — El diseño experimental del Diario de misiones y del mapa del mundo se ha retirado porque provocaba errores en el juego. El aspecto y el comportamiento originales de Blizzard permanecen intactos; la pestaña independiente de misiones de mundo sigue disponible.",
    ["wn_403_world_quest_tab"] = "Cambio — El antiguo panel de misiones de mundo situado junto al mapa ha sido sustituido por una pestaña nativa dentro del Diario de misiones, reuniendo las misiones y la navegación del mapa en una sola ventana.",
    ["wn_403_world_quest_cards"] = "Novedad — Las misiones de mundo se muestran como tarjetas compactas con icono de recompensa, color de rareza, marcador de élite, zona y tiempo restante. Incluyen búsqueda, orden por tiempo, recompensa, zona o nombre, barra de desplazamiento arrastrable y navegación al mapa con un clic.",
    ["wn_403_world_quest_sort"] = "Corrección — La ordenación de misiones de mundo admite ahora tiempos, datos de recompensa e identificadores de misión ausentes o no numéricos. Las entradas vacías se colocan de forma coherente, los valores iguales se resuelven por identificador y ambos sentidos de ordenación son explícitos.",
    ["wn_403_bags_separate_skin"] = "Novedad — El modo de bolsas separadas conserva las ventanas individuales de Blizzard y les aplica un diseño TomoMod completo: paneles y cabeceras oscuros, bordes azules, títulos Poppins, casillas hundidas, iconos recortados y realce al pasar el cursor. Volver al modo combinado o desactivar las bolsas restaura el aspecto nativo original.",
    ["wn_403_bags_tracked_currencies"] = "Novedad — La barra lateral de Bags V4 muestra ahora cada moneda marcada Mostrar en la mochila en mosaicos compactos de dos columnas, con icono, cantidad formateada y descripción nativa. La sección localizada aparece solo cuando hay monedas seguidas y se actualiza al cambiar sus datos.",
    ["wn_403_bags_currency_reliability"] = "Corrección — Ocultar la mochila de Blizzard en modo combinado podía reducir a una la capacidad calculada de monedas seguidas. TomoMod conserva ahora los tres espacios habituales solo en ese modo y lee directamente el estado persistente isShowInBackpack, para que las monedas adicionales dejen de desaparecer.",
    ["wn_403_color_picker_skin"] = "Novedad — El selector de color global de Blizzard cuenta ahora con un diseño TomoMod completo, con cuerpo, cabecera y pie oscuros en capas, bordes azules, tipografía Poppins y controles a juego. El campo hexadecimal, las muestras de color, las zonas de valor y alfa y el control de opacidad comparten el mismo estilo.",
    ["wn_403_color_picker_compatibility"] = "Cambio — El diseño admite tanto la disposición Retail actual como la heredada de ColorPickerFrame, se inicializa cuando está disponible el selector de Blizzard de carga bajo demanda y vuelve a aplicarse cada vez que se abre. Blizzard conserva la selección del color y las funciones de confirmación y cancelación.",
    ["wn_403_color_picker_buttons"] = "Corrección — Los botones de panel Retail ya no dibujan sus texturas persistentes Left, Middle y Right sobre el diseño TomoMod. El botón de cierre personalizado también conserva la función de cancelación original de Blizzard y los valores de color anteriores.",
    ["wn_403_waypoint_inner_ring"] = "Cambio — La baliza del punto de ruta conserva únicamente su anillo interior compacto. El gran halo exterior translúcido y sus ajustes de color y tamaño se han eliminado para ofrecer un marcador más limpio, mientras que el haz, el punto central y la flecha de navegación mantienen su comportamiento actual.",
    ["wn_403_survival_tab"] = "Novedad — El Análisis de run Mítica+ incorpora una pestaña Supervivencia junto al Resumen. Ambas vistas comparten la misma ventana, así que el resumen del run, el rendimiento del grupo y los splits quedan a un clic del análisis de muertes.",
    ["wn_403_survival_chronology"] = "Novedad — La pestaña Supervivencia enumera cada muerte registrada durante la llave en orden cronológico, con su tiempo de run y el color de clase del jugador. Al seleccionar una fila se abre esa muerte en el panel de detalle.",
    ["wn_403_survival_detail"] = "Novedad — Tus propias muertes se muestran al completo: el evento fatal con su icono, nombre, daño y overkill, tu salud máxima y los diez últimos eventos antes de morir, cada uno con el tiempo que lo separa del golpe mortal y la salud que te quedaba.",
    ["wn_403_survival_collector"] = "Novedad — El recolector de muertes ahora se carga con el propio TomoMod en lugar del Estudio Mítica+ bajo demanda. El seguimiento empieza con la llave, de modo que ya no se pierde un run porque el Estudio no se hubiera abierto todavía.",
    ["wn_403_survival_unit_events"] = "Cambio — Las muertes se leen a partir de las transiciones de estado de las unidades y no del registro de combate, protegido en el cliente actual. Los eventos de salud e indicadores del grupo ofrecen la misma cronología sin tocarlo.",
    ["wn_403_survival_recap_bridge"] = "Cambio — Tu cronología previa a la muerte se copia del resumen de muerte de Blizzard a través del puente protegido de TomoDamageMeter. Ese resumen no es legible en el instante de morir, así que se reintenta durante unos dos segundos y medio antes de marcar la muerte como sin detalle legible.",
    ["wn_403_survival_reliability"] = "Cambio — El número de muertes observadas se contrasta con el propio contador del juego para la llave. Un run coincidente se informa como seguimiento completo, mientras que una llave iniciada tarde o recargada a mitad de run se informa como seguimiento parcial con ambas cifras, en lugar de presentar una lista incompleta como si fuera toda la historia.",
    ["wn_403_survival_history"] = "Novedad — La cronología de muertes se guarda en la instantánea del run junto a los datos de rendimiento existentes, así que reabrir una llave antigua desde el Historial de runs muestra las muertes que ese run tuvo realmente en vez de nada.",
    ["wn_403_survival_localization"] = "Cambio — Todas las etiquetas de la pestaña Supervivencia — las propias pestañas, la cronología, el estado del seguimiento, el evento fatal, la línea temporal y los mensajes que aparecen cuando no hay detalle — están traducidas a los seis idiomas compatibles.",
})

TomoMod_RegisterLocale("itIT", {
    ["wn_403_quest_journal_skin_removed"] = "Rimosso — Lo stile sperimentale del Registro missioni e della mappa del mondo è stato rimosso perché causava errori nel gioco. L'aspetto e il comportamento originali di Blizzard restano invariati; la scheda indipendente delle missioni mondiali è ancora disponibile.",
    ["wn_403_world_quest_tab"] = "Modifica — Il precedente pannello delle missioni mondiali accanto alla mappa è stato sostituito da una scheda nativa nel Registro missioni, riunendo missioni e navigazione della mappa in un'unica finestra.",
    ["wn_403_world_quest_cards"] = "Novità — Le missioni mondiali sono mostrate come schede compatte con icona della ricompensa, colore di rarità, indicatore élite, zona e tempo rimanente. Sono inclusi ricerca, ordinamento per tempo, ricompensa, zona o nome, barra di scorrimento trascinabile e navigazione sulla mappa con un clic.",
    ["wn_403_world_quest_sort"] = "Correzione — L'ordinamento delle missioni mondiali ora gestisce tempi, dati delle ricompense e ID missione mancanti o non numerici. Le voci vuote vengono ordinate in modo coerente, i valori uguali sono risolti tramite l'ID missione ed entrambi i versi di ordinamento sono espliciti.",
    ["wn_403_bags_separate_skin"] = "Novità — La modalità con borse separate mantiene le singole finestre contenitore di Blizzard e applica uno stile TomoMod completo: pannelli e intestazioni scuri, bordi azzurri, titoli Poppins, slot incassati, icone ritagliate e risalto al passaggio. Tornando alla modalità combinata o disattivando le borse viene ripristinato l'aspetto nativo originale.",
    ["wn_403_bags_tracked_currencies"] = "Novità — La barra laterale di Bags V4 elenca ora ogni valuta contrassegnata Mostra nello zaino in riquadri compatti su due colonne, con icona, quantità formattata e tooltip nativo. La sezione localizzata appare solo quando ci sono valute tracciate e si aggiorna al variare dei loro dati.",
    ["wn_403_bags_currency_reliability"] = "Correzione — Nascondere lo zaino Blizzard in modalità combinata poteva ridurre a uno la capacità calcolata delle valute tracciate. TomoMod mantiene ora i tre spazi tradizionali soltanto in questa modalità e legge direttamente lo stato persistente isShowInBackpack, così le valute aggiuntive non scompaiono più.",
    ["wn_403_color_picker_skin"] = "Novità — Il selettore colore globale di Blizzard dispone ora di uno stile TomoMod completo, con corpo, intestazione e piè di pagina scuri a livelli, bordi azzurri, carattere Poppins e controlli coordinati. Campo esadecimale, campioni colore, aree valore e alfa e cursore di opacità condividono lo stesso aspetto.",
    ["wn_403_color_picker_compatibility"] = "Modifica — Lo stile supporta sia il layout Retail attuale sia quello precedente di ColorPickerFrame, si inizializza quando il selettore Blizzard a caricamento differito diventa disponibile e viene riapplicato a ogni apertura. La selezione del colore e le funzioni di conferma e annullamento restano gestite da Blizzard.",
    ["wn_403_color_picker_buttons"] = "Correzione — I pulsanti dei pannelli Retail non ridisegnano più le texture persistenti Left, Middle e Right sopra lo stile TomoMod. Anche il pulsante di chiusura personalizzato conserva la funzione di annullamento originale di Blizzard e i valori colore precedenti.",
    ["wn_403_waypoint_inner_ring"] = "Modifica — Il segnalatore del punto di navigazione mantiene soltanto il suo anello interno compatto. Il grande alone esterno traslucido e i relativi aggiornamenti di colore e dimensione sono stati rimossi per un indicatore più pulito, mentre il raggio, il punto centrale e la freccia di navigazione conservano il comportamento attuale.",
    ["wn_403_survival_tab"] = "Novità — L'Analisi run Mitica+ guadagna una scheda Sopravvivenza accanto al Riepilogo. Le due viste condividono la stessa finestra, così riepilogo della run, prestazioni del gruppo e split restano a un clic dall'analisi delle morti.",
    ["wn_403_survival_chronology"] = "Novità — La scheda Sopravvivenza elenca ogni morte registrata durante la chiave in ordine cronologico, con il suo tempo di run e il colore di classe del giocatore. Selezionando una riga si apre quella morte nel pannello di dettaglio.",
    ["wn_403_survival_detail"] = "Novità — Le tue morti sono mostrate per intero: l'evento fatale con icona, nome, danni e overkill, la tua salute massima e gli ultimi dieci eventi prima della morte, ciascuno con il tempo che lo separa dal colpo fatale e la salute che ti restava.",
    ["wn_403_survival_collector"] = "Novità — Il raccoglitore di morti viene ora caricato con TomoMod stesso anziché con lo Studio Mitica+ a richiesta. Il tracciamento parte insieme alla chiave, quindi una run non va più persa perché lo Studio non era ancora stato aperto.",
    ["wn_403_survival_unit_events"] = "Modifica — Le morti sono lette dalle transizioni di stato delle unità anziché dal registro di combattimento, protetto sul client attuale. Gli eventi di salute e di stato del gruppo forniscono la stessa cronologia senza toccarlo.",
    ["wn_403_survival_recap_bridge"] = "Modifica — La tua cronologia precedente alla morte viene copiata dal riepilogo morte di Blizzard tramite il ponte protetto di TomoDamageMeter. Quel riepilogo non è leggibile nell'istante della morte, perciò viene ritentato per circa due secondi e mezzo prima di segnare la morte come priva di dettagli leggibili.",
    ["wn_403_survival_reliability"] = "Modifica — Il numero di morti osservate viene confrontato con il contatore del gioco per la chiave. Una run coerente è segnalata come tracciamento completo, mentre una chiave presa in corsa o ricaricata a metà run è segnalata come tracciamento parziale con entrambi i valori, invece di presentare un elenco incompleto come se fosse tutto.",
    ["wn_403_survival_history"] = "Novità — La cronologia delle morti è salvata nell'istantanea della run insieme ai dati di prestazione esistenti: riaprire una chiave passata dalla Cronologia run mostra le morti che quella run ha davvero avuto invece di niente.",
    ["wn_403_survival_localization"] = "Modifica — Tutte le etichette della scheda Sopravvivenza — le schede stesse, la cronologia, lo stato del tracciamento, l'evento fatale, la timeline e i messaggi mostrati quando non c'è dettaglio — sono tradotte in tutte e sei le lingue supportate.",
